#include "CloseToHSL/Core/Virtualization/SecureCompute/Compatibility/Projection/PrivilegedExecutionStateProjectionService.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ auto d=std::make_shared<PrivilegedExecutionStateDescriptor>(PrivilegedExecutionStateDescriptor{1,2,{3},true,{PrivilegedControlRegisterKind::GuestCr0,1},{PrivilegedControlRegisterKind::GuestCr4,2},{3,1,3,2,true},PrivilegedExecutionStateEvidenceClass::GuestVisibleReadOnlyProjection,PrivilegedExecutionStateMigrationClass::RevalidatedAfterRestore}); PrivilegedExecutionStateProjectionService svc; auto req=[&](PrivilegedControlRegisterKind reg,bool visibility,bool migration,bool proof){ return std::make_shared<PrivilegedExecutionStateProjectionRequest>(reg,d,1,2,PrivilegedExecutionStateEpoch{3},visibility,migration,proof); }; auto r=svc.Project(req(PrivilegedControlRegisterKind::GuestCr4,true,true,true)); assert(r->IsAllowed && r->Value==2 && !r->MutationAuthorized && !r->BackendSuccessAuthorized && !r->CompletionPublicationAuthorized); assert(svc.Project(req(PrivilegedControlRegisterKind::GuestCr0,false,true,true))->Decision==PrivilegedExecutionStateProjectionDecision::DeniedNoSecureVisibility); assert(svc.Project(req(PrivilegedControlRegisterKind::GuestCr0,true,false,true))->Decision==PrivilegedExecutionStateProjectionDecision::DeniedNoMigrationClass); assert(svc.Project(req(PrivilegedControlRegisterKind::GuestCr0,true,true,false))->Decision==PrivilegedExecutionStateProjectionDecision::DeniedNoConformanceProof); assert(svc.Project(req(static_cast<PrivilegedControlRegisterKind>(3),true,true,true))->Decision==PrivilegedExecutionStateProjectionDecision::DeniedUnsupportedRegister); }
